#!/usr/bin/env python3
"""Close exactly the observed rows_finish RowView reversal boundary."""
import argparse,hashlib,json,pathlib,re,shutil
HERE=pathlib.Path(__file__).resolve().parent
p=argparse.ArgumentParser();p.add_argument('--input',type=pathlib.Path,required=True);p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();assert not a.output.exists();assert not a.output.absolute().is_relative_to(a.input.resolve());assert not any(x.is_symlink() for x in a.input.rglob('*'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();pins={str(p.relative_to(a.input)):sha(p) for p in a.input.rglob('*.bend')};assert len(pins)==29 and pins==json.loads((HERE/'closed-frame-output-pins.json').read_text());overlay=json.loads((a.input/'overlay.json').read_text());cache=json.loads((a.input/'cache-specialization.json').read_text());assert cache==overlay['cacheSpecialization'];assert cache['runtimeClosure']==cache['specializedClosure']==overlay['sources']==pins;assert cache['runtimeClosureSHA256']==hashlib.sha256(json.dumps(pins,sort_keys=True,separators=(',',':')).encode()).hexdigest()
name='experiments/s-integrate/observations.bend';source=(a.input/name).read_text();m=re.search(r'^def rows_finish\(',source,re.M);tail=source[m.start():];n=re.search(r'\n(?:def |type )',tail);old=tail[:n.start()+1] if n else tail;new=old.replace('def rows_finish(','def prototype_closed_observation_rows_finish(',1);new=re.sub(r'-(\w+):\s*(Data|Type)',r'~\1: \2',new);assert 'List.reverse(&2,RowView<V,AV,F>,values)' in new
source=source.replace('def rows_advance(',new+'\ndef rows_advance(',1);assert source.count('case 0n: rows_finish(M,A,F,V,AV,state)')==1;source=source.replace('case 0n: rows_finish(M,A,F,V,AV,state)','case 0n: prototype_closed_observation_rows_finish(~M,~A,~F,~V,~AV,state)');assert old in source
shutil.copytree(a.input,a.output);(a.output/name).write_text(source);newpins={str(p.relative_to(a.output)):sha(p) for p in a.output.rglob('*.bend')};assert [k for k in pins if pins[k]!=newpins[k]]==[name]
cache['runtimeClosure']=newpins;cache['specializedClosure']=newpins.copy();cache['runtimeClosureSHA256']=hashlib.sha256(json.dumps(newpins,sort_keys=True,separators=(',',':')).encode()).hexdigest();overlay['sources']=newpins;overlay['cacheSpecialization']=cache
for name,value in [('overlay.json',overlay),('cache-specialization.json',cache),('closed-observation.json',{'status':'UNVERIFIED_SOURCE_HYPOTHESIS','inputPins':pins,'outputPins':newpins,'recipeSHA256':sha(pathlib.Path(__file__))})]:(a.output/name).write_text(json.dumps(value,indent=2)+'\n')
print(a.output/'experiments/s-integrate')
